package com.daniil.wristlens.wear;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Color;import android.widget.*;import androidx.work.*;import com.daniil.wristlens.shared.*;import java.util.concurrent.TimeUnit;
final class AutoSave {
 static final String WORK="wristlens-originals";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("auto_save",0);}static boolean enabled(Context c){return prefs(c).getBoolean("enabled",false);}
 static void enqueue(Context c){if(enabled(c))WorkManager.getInstance(c).enqueueUniqueWork(WORK,ExistingWorkPolicy.APPEND_OR_REPLACE,new OneTimeWorkRequest.Builder(AutoSaveWorker.class).addTag(WORK).setBackoffCriteria(BackoffPolicy.EXPONENTIAL,30,TimeUnit.SECONDS).build());}
 // Persist the target and initial cursor before scheduling work.
 @android.annotation.SuppressLint("ApplySharedPref")
 static void addSettings(Activity a,LinearLayout col,MediaClient client,String node){CheckBox toggle=Controls.checkBox(a);toggle.setText(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_01));toggle.setTextColor(Color.WHITE);toggle.setChecked(enabled(a));col.addView(toggle);TextView status=Controls.text(a,prefs(a).getString("status",""),12,Color.LTGRAY);col.addView(status);
 boolean[] silent={false};toggle.setOnCheckedChangeListener((v,on)->{if(silent[0])return;if(!on){prefs(a).edit().putBoolean("enabled",false).apply();WorkManager.getInstance(a).cancelAllWorkByTag(WORK);Controls.saved(a);return;}toggle.setEnabled(false);client.request(Wire.object("op","list"),j->{boolean saved=prefs(a).edit().putBoolean("enabled",true).putString("node",node).putLong("cursor",j.optLong("cursor")).putString("status","").putString("skipped","").commit();toggle.setEnabled(true);if(!saved){silent[0]=true;toggle.setChecked(false);silent[0]=false;status.setText(Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_09));return;}Controls.saved(a);enqueue(a);if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},90);},e->{silent[0]=true;toggle.setChecked(false);silent[0]=false;toggle.setEnabled(true);status.setText(e);});});
 CopySettings.add(a,col);col.addView(Controls.button(a,com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_03),()->{enqueue(a);status.setText(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_04));}));Handler h=new Handler(Looper.getMainLooper());Runnable tick=new Runnable(){public void run(){status.setText(Strings.message(prefs(a).getString("status","")));status.setVisibility(status.getText().length()==0?android.view.View.GONE:android.view.View.VISIBLE);h.postDelayed(this,1000);}};
 status.setVisibility(status.getText().length()==0?android.view.View.GONE:android.view.View.VISIBLE);
 col.addOnAttachStateChangeListener(new android.view.View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(android.view.View v){h.post(tick);}public void onViewDetachedFromWindow(android.view.View v){h.removeCallbacks(tick);}});}
}
